  if(form){Array.prototype.slice.call(form.elements).forEach(el=>{if(el.type==='file'||(!el.name&&!el.id))return;draft.fields.push({name:el.name,id:el.id,value:el.value,checked:el.checked,disabled:el.disabled})});draft.urbanChanged=form.getAttribute('data-urban-changed')==='true';const urban=$('#fillUrban',form);if(urban)draft.urbanOriginal=urban.getAttribute('data-original')}
