  if(form){const elements=Array.prototype.slice.call(form.elements);draft.fields.forEach(field=>{const el=elements.filter(x=>field.name?x.name===field.name:x.id===field.id)[0];if(!el)return;el.value=field.value;el.checked=field.checked;el.disabled=field.disabled});if(draft.form==='fillForm'){form.setAttribute('data-preserve-total','true');form.setAttribute('data-language-restored','true');form.setAttribute('data-urban-changed',draft.urbanChanged?'true':'false');const urban=$('#fillUrban',form);if(urban&&draft.urbanOriginal!==null)urban.setAttribute('data-original',draft.urbanOriginal)}}
