async function importGenericRows(rows,replace){
  const vehicles=replace?[]:state.vehicles.slice(),fills=[],bad=[],seen=new Set(),ids=new Set((replace?[]:state.fillups).map(f=>f.id));let duplicates=0;
  (replace?[]:state.fillups).forEach(f=>seen.add(f.vehicleId+'|'+FuelLogData.sourceKey(Object.assign({},f,{currency:recordCurrency(f)}))));
  for(let i=0;i<rows.length;i++){
    const r=rows[i]||{},date=flexDate(rowValue(r,['date','datetime','timestamp','data','data_hora','datahora'])),odometer=flexNum(rowValue(r,['odometer','odometer_km','mileage','km','kms','quilometragem','conta_quilometros'])),litres=flexNum(rowValue(r,['litres','liters','litros','quantity','volume','combustivel_litros']));
    let total=flexNum(rowValue(r,['total_cost','total_cost_eur','total','cost','amount','custo','custo_total','preco_total','valor'])),price=flexNum(rowValue(r,['price_per_litre','price_per_liter','price_l','unit_price','price','preco_litro','preco_por_litro']));
    if(!isFinite(total)&&isFinite(price)&&isFinite(litres))total=price*litres;if(!isFinite(price)&&isFinite(total)&&litres>0)price=total/litres;
    const currency=String(rowValue(r,['currency','moeda'])||'EUR').toUpperCase();
    if(!date||!isFinite(odometer)||odometer<0||!isFinite(litres)||litres<=0||!isFinite(total)||total<0||!isFinite(price)||price<0||!/^[A-Z]{3}$/.test(currency)){bad.push(i+2);continue}
    const fuelType=String(rowValue(r,['fuel_type','fuel','combustivel','tipo_combustivel'])||''),rawFuel=String(rowValue(r,['fuel_id','fuelid','combustivel_id'])||''),fuelId=FuelLogFuels.LIST.some(f=>f.id===rawFuel)?rawFuel:FuelLogFuels.guess(fuelType),name=String(rowValue(r,['vehicle','vehicle_name','car','car_name','viatura','veiculo'])||'').trim();
    let v=name?vehicles.find(v=>v.name.toLowerCase()===name.toLowerCase()):vehicles.find(v=>v.id===state.settings.activeVehicle)||vehicles[0];
    if(!v){v={id:uid(),name:name||tr("ui.imported_vehicle"),make:'',model:'',registration:'',currency,preferredFuel:fuelId||null,initialOdometer:0};vehicles.push(v)}
    const f={vehicleId:v.id,date,odometer,litres,totalCost:total,pricePerLitre:price,currency,station:String(rowValue(r,['station','gas_station','fuel_station','posto','posto_abastecimento'])||''),stationId:String(rowValue(r,['station_id','stationid'])||'')||null,country:String(rowValue(r,['country','pais'])||'')||null,fuelId:fuelId||null,fuelType:fuelId?FuelLogFuels.label(fuelId):fuelType,fullTank:flexBool(rowValue(r,['full_tank','full','tank_full','deposito_cheio','ateste'])),notes:String(rowValue(r,['notes','note','comment','comments','notas','observacoes'])||''),updatedAt:new Date().toISOString()};
    const address=String(rowValue(r,['station_address','address'])||''),lat=flexNum(rowValue(r,['latitude','lat'])),lon=flexNum(rowValue(r,['longitude','lon'])),external=String(rowValue(r,['jerrycan_station_id'])||'');
    if(address||external||(isFinite(lat)&&isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180)){f.stationLocation={name:f.station,address,externalIds:{}};if(external)f.stationLocation.externalIds.jerrycan=external;if(isFinite(lat)&&isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180){f.stationLocation.latitude=lat;f.stationLocation.longitude=lon}}
    const city=flexNum(rowValue(r,['city_percentage','cityPercentage']));if(isFinite(city)&&city>=0&&city<=1)f.cityPercentage=city;
    const key=f.vehicleId+'|'+FuelLogData.sourceKey(f);if(seen.has(key)){duplicates++;continue}seen.add(key);
    const supplied=String(rowValue(r,['id','uuid','record_id'])||'');f.id=supplied&&!ids.has(supplied)?supplied:uid();ids.add(f.id);fills.push(f);
  }
  if(!fills.length&&!duplicates)throw new Error(tr("ui.no_usable_fuel_records_were_detected_check"));
  const batch={replace,vehicles:replace?vehicles:vehicles.filter(v=>!state.vehicles.some(old=>old.id===v.id)),fillups:fills,settings:[]};
  const active=vehicles.find(v=>v.id===state.settings.activeVehicle)||vehicles[0];if(active)batch.settings.push({key:'activeVehicle',value:active.id});
  if(!await previewImport(batch,rows.length+(" "+tr("ui.rows")+" ")+fills.length+(" "+tr("import.to_import_suffix")+" ")+duplicates+(" "+tr("import.duplicates_suffix"))+(bad.length?("\n"+tr("ui.invalid_rows_excluded")+" ")+bad.join(', '):'')))return null;
  await FuelDB.commitImport(batch);return fills.length;
}
async function importFuelLogBackup(data,replace){
  if(!data||data.format!=='FuelLog'||!Array.isArray(data.vehicles)||!Array.isArray(data.fillups)||!Number.isInteger(data.version)||data.version<1||data.version>4)throw new Error(tr("ui.invalid_or_unsupported_fuellog_backup"));
  const vids=new Set(),fids=new Set();for(const v of data.vehicles){if(!v||typeof v.id!=='string'||!v.id||typeof v.name!=='string'||vids.has(v.id))throw new Error(tr("ui.invalid_or_duplicate_vehicle"));vids.add(v.id)}
  for(const f of data.fillups){if(!f||typeof f.id!=='string'||!f.id||fids.has(f.id)||!vids.has(f.vehicleId)||!flexDate(f.date)||typeof f.odometer!=='number'||f.odometer<0||!isFinite(f.odometer)||typeof f.litres!=='number'||f.litres<=0||!isFinite(f.litres)||typeof f.totalCost!=='number'||f.totalCost<0||!isFinite(f.totalCost)||typeof f.fullTank!=='boolean'||(f.currency&&!/^[A-Z]{3}$/.test(f.currency)))throw new Error(tr("ui.invalid_fill_up_or_vehicle_reference"));fids.add(f.id)}
  const promos=data.promos||[],settings=data.settings||[];if(!Array.isArray(promos)||!Array.isArray(settings)||promos.some(p=>!p||typeof p.id!=='string')||settings.some(s=>!s||typeof s.key!=='string'))throw new Error(tr("ui.invalid_backup_settings_or_promos"));
  const vehicles=data.vehicles.map(v=>Object.assign({},v)),fills=data.fillups.map(f=>Object.assign({},f,{currency:f.currency||'EUR'}));
  // Remap conflicting local IDs during merge rather than overwriting unrelated data.
  if(!replace){const remap={};vehicles.forEach(v=>{const old=state.vehicles.find(x=>x.id===v.id);if(old&&JSON.stringify(old)!==JSON.stringify(v)){remap[v.id]=uid();v.id=remap[v.id]}});fills.forEach(f=>{if(remap[f.vehicleId])f.vehicleId=remap[f.vehicleId]});}
  // Native backups are authoritative: distinct local IDs stay distinct, even
  // when the numeric/date values happen to coincide.
  const importFills=fills.filter(f=>{if(replace)return true;const old=state.fillups.find(x=>x.id===f.id);if(!old)return true;if(JSON.stringify(Object.assign({},old,{currency:recordCurrency(old)}))===JSON.stringify(f))return false;f.id=uid();return true});
  const known=new Set((replace?[]:state.vehicles).concat(vehicles).map(v=>v.id)),active=settings.find(s=>s.key==='activeVehicle');
  const chosen=replace?(active&&vids.has(active.value)?active.value:(vehicles[0]&&vehicles[0].id)):state.settings.activeVehicle;
  const batch={replace,vehicles,fillups:importFills,promos:promos.map(p=>{const copy=Object.assign({},p);if(!replace&&state.promos.some(x=>x.id===p.id&&JSON.stringify(x)!==JSON.stringify(p)))copy.id=uid();return copy}),settings:replace?settings.filter(s=>s.key!=='lastBackup'&&s.key!=='activeVehicle'&&s.key!=='schemaMigrated'):[]};
  if(chosen&&known.has(chosen))batch.settings.push({key:'activeVehicle',value:chosen});
  if(!await previewImport(batch,importFills.length+(" "+tr("ui.fill_ups_in_a_fuellog_backup")+"\n")+(replace?tr("ui.backup_promos_and_settings_will_also_be"):tr("ui.existing_settings_are_preserved"))))return null;
  await FuelDB.commitImport(batch);return importFills.length;
}
async function importData(e){
  const file=e.target.files&&e.target.files[0];if(!file)return;
  try{
    await loadDeferredScripts();
    if(file.size>5*1024*1024)throw new Error(tr("ui.for_older_iphones_import_files_are_limited"));
    const buffer=await readFileBuffer(file),header=String.fromCharCode.apply(null,new Uint8Array(buffer,0,Math.min(8,buffer.byteLength)));let count;
    if(header==='bplist00')count=await importJerrycan(FuelLogBplist.decode(buffer));
    else{
      if(/\.jerrycan$/i.test(file.name))throw new Error(tr("ui.this_jerrycan_file_is_not_a_supported"));
      const text=(await readFileText(file)).replace(/^\uFEFF/,'').trim();if(!text)throw new Error(tr("ui.the_selected_file_is_empty"));
      let data,rows,isBackup=false;if(text[0]==='{'||text[0]==='['){data=JSON.parse(text);isBackup=!!(data&&data.format==='FuelLog');if(!isBackup)rows=extractRowsFromJson(data)}else rows=parseDelimited(text,guessDelimiter(text));
      const mode=await chooseImportMode();if(!mode)return;count=isBackup?await importFuelLogBackup(data,mode.mode==='replace'):await importGenericRows(rows||[],mode.mode==='replace');
    }
    if(count===null)return;await refresh();render();toast((tr("ui.imported")+" ")+count+(" "+tr("ui.fill_ups")));
  }catch(err){await appDialog({title:tr("ui.import_failed"),body:window.FuelLogI18n.message(err.message||err),confirmLabel:tr("ui.ok"),cancelLabel:null})}finally{e.target.value=''}
}

async function init(){wireLanguagePicker();registerFuelServiceWorker();await FuelDB.open();if(FuelProviders.legacyIOS())document.documentElement.classList.add('legacy-ios');await refresh();if(!state.vehicles.length){const first={id:uid(),name:tr("ui.my_car"),registration:'',make:'',model:'',fuelType:'Diesel B7',preferredFuel:'DIESEL_B7',initialOdometer:0};await FuelDB.put('vehicles',first);await setSetting('activeVehicle',first.id);await refresh()}await migrateData();render();scheduleAfterFirstPaint(function(){loadDeferredScripts().then(function(){if(state.route==='dashboard')render()}).catch(console.error)});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.deferredPrompt=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(!state.deferredPrompt)return;state.deferredPrompt.prompt();await state.deferredPrompt.userChoice;state.deferredPrompt=null;$('#installBtn').classList.add('hidden')};const status=()=>{$('#offlineBadge').textContent=navigator.onLine?tr("ui.online"):tr("ui.offline_ready");if(state.route==='prices')updatePriceOfflineUi();if(state.route==='settings'){if(navigator.onLine)checkAppUpdate();else updateSettingsVersionUi()}};window.addEventListener('online',status);window.addEventListener('offline',status);status();const onPricesResize=()=>{if(state.route==='prices'&&priceMap&&priceMap.map)setTimeout(()=>priceMap.map.invalidateSize(),250)};window.addEventListener('orientationchange',onPricesResize);window.addEventListener('resize',onPricesResize);$$('[data-route]',document).forEach(b=>b.onclick=()=>route(b.dataset.route))}
init().catch(e=>{$('#app').innerHTML=`<div class="empty">${esc(tr("diagnostic.fuellog_could_not_start_message",{message:window.FuelLogI18n.message(e.message)}))}</div>`;console.error(e)});
